57	// NewHandler builds the public HTTP surface backed by s.
58	func NewHandler(s *store.Store) http.Handler {
59		mux := http.NewServeMux()
60	
61		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
62			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
63		})
64	
65		mux.HandleFunc("POST /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
66			handlePostChanges(s, w, r)
67		})
68		mux.HandleFunc("GET /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
69			handleListChanges(s, w, r)
70		})
71		mux.HandleFunc("POST /v1/documents/{documentID}/merge", func(w http.ResponseWriter, r *http.Request) {
72			handleMergeChange(s, w, r)
73		})
74		mux.HandleFunc("POST /v1/documents/{documentID}/snapshots", func(w http.ResponseWriter, r *http.Request) {
75			handlePostSnapshot(s, w, r)
76		})
77		mux.HandleFunc("GET /v1/documents/{documentID}/snapshots/{cursor}", func(w http.ResponseWriter, r *http.Request) {
78			handleGetSnapshot(s, w, r)
79		})
80		mux.HandleFunc("POST /v1/documents/{documentID}/restore", func(w http.ResponseWriter, r *http.Request) {
81			handleRestore(s, w, r)
82		})
83	
84		// ServeMux treats the empty document segment in /v1/documents//... as an
85		// unclean path and answers with a 307 HTML redirect (a 404 in a real
86		// client). The API contract is a 400 JSON error, so intercept those paths
87		// before the mux sees them.
88		return emptyIDGuard(mux)
