91	// emptyIDGuard rejects requests whose documentID path segment is empty with a
92	// 400 JSON error instead of letting ServeMux emit its HTML redirect.
93	func emptyIDGuard(next http.Handler) http.Handler {
94		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
95			p := r.URL.Path
96			if strings.HasPrefix(p, "/v1/documents//") {
97				writeError(w, http.StatusBadRequest, "documentID must be a non-empty string")
98				return
99			}
100			next.ServeHTTP(w, r)
101		})
102	}
