114	func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
115		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
116	
117		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
118		if err != nil || mediaType != "application/json" {
119			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
120			return
121		}
122	
123		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
124		var req postRequest
125		dec := json.NewDecoder(r.Body)
126		if err := dec.Decode(&req); err != nil {
127			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
128			return
129		}
130		// Reject trailing data after the JSON object.
131		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
132			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
133			return
134		}
135	
136		if req.DeviceID == "" {
137			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
138			return
139		}
140		if len(req.Changes) == 0 {
141			writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
142			return
143		}
144	
145		changes := make([]store.Change, len(req.Changes))
146		seen := make(map[string]struct{}, len(req.Changes))
147		for i, c := range req.Changes {
148			if c.ID == "" {
149				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
150				return
151			}
152			if len(c.Payload) == 0 {
153				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
154				return
155			}
156			if _, dup := seen[c.ID]; dup {
157				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
158				return
159			}
160			seen[c.ID] = struct{}{}
161			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
162		}
163	
164		results, err := s.PostChanges(documentID, changes)
165		if err != nil {
166			var conflict *store.ErrConflict
167			if errors.As(err, &conflict) {
168				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
169				return
170			}
171			writeError(w, http.StatusInternalServerError, "failed to commit changes")
172			return
173		}
174	
175		writeJSON(w, http.StatusOK, map[string]any{"results": results})
176	}
