178	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
179		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
180	
181		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
182		if err != nil || mediaType != "application/json" {
183			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
184			return
185		}
186	
187		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
188		var req mergeRequest
189		dec := json.NewDecoder(r.Body)
190		if err := dec.Decode(&req); err != nil {
191			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
192			return
193		}
194		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
195			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
196			return
197		}
198	
199		if req.DeviceID == "" {
200			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
201			return
202		}
203		// baseCursor must be present and a non-negative integer (no fractions,
204		// strings, booleans or null).
205		if len(req.BaseCursor) == 0 {
206			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
207			return
208		}
209		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
210		if !ok {
211			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
212			return
213		}
214		if req.Change == nil {
215			writeError(w, http.StatusBadRequest, "change must be an object")
216			return
217		}
218		if req.Change.ID == "" {
219			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
220			return
221		}
222		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
223			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
224			return
225		}
226	
227		result, err := s.MergeChange(documentID, baseCursor, store.Change{
228			ID:       req.Change.ID,
229			DeviceID: req.DeviceID,
230			Payload:  req.Change.Payload,
231		})
232		if err != nil {
233			var conflict *store.ErrConflict
234			switch {
235			case errors.Is(err, store.ErrStaleCursor):
236				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
237				return
238			case errors.As(err, &conflict):
239				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
240				return
241			default:
242				writeError(w, http.StatusInternalServerError, "failed to merge change")
243				return
244			}
245		}
246	
247		writeJSON(w, http.StatusOK, result)
248	}
