250	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
251		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
252	
253		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
254		if err != nil || mediaType != "application/json" {
255			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
256			return
257		}
258	
259		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
260		var req snapshotPostRequest
261		dec := json.NewDecoder(r.Body)
262		if err := dec.Decode(&req); err != nil {
263			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
264			return
265		}
266		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
267			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
268			return
269		}
270	
271		cursor, ok := parseNonNegativeInt(req.Cursor)
272		if !ok {
273			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
274			return
275		}
276		if len(req.State) == 0 {
277			writeError(w, http.StatusBadRequest, "state is required")
278			return
279		}
280	
281		created, err := s.PutSnapshot(documentID, cursor, req.State)
282		if err != nil {
283			var conflict *store.ErrSnapshotConflict
284			switch {
285			case errors.Is(err, store.ErrSnapshotBase):
286				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
287				return
288			case errors.As(err, &conflict):
289				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
290				return
291			default:
292				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
293				return
294			}
295		}
296	
297		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
298	}
