300	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
301		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
302	
303		cursor, ok := parseCursorPath(r.PathValue("cursor"))
304		if !ok {
305			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
306			return
307		}
308	
309		state, err := s.GetSnapshot(documentID, cursor)
310		if err != nil {
311			if errors.Is(err, store.ErrSnapshotNotFound) {
312				writeError(w, http.StatusNotFound, "snapshot not found")
313				return
314			}
315			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
316			return
317		}
318	
319		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
320	}
