322	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
323		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
324	
325		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
326		if err != nil || mediaType != "application/json" {
327			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
328			return
329		}
330	
331		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
332		var req restoreRequest
333		dec := json.NewDecoder(r.Body)
334		if err := dec.Decode(&req); err != nil {
335			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
336			return
337		}
338		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
339			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
340			return
341		}
342	
343		if req.DeviceID == "" {
344			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
345			return
346		}
347		if req.ChangeID == "" {
348			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
349			return
350		}
351		// snapshotCursor must be present and a positive integer (no fractions,
352		// strings, booleans, null or zero).
353		if len(req.SnapshotCursor) == 0 {
354			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
355			return
356		}
357		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
358		if !ok {
359			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
360			return
361		}
362	
363		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
364		if err != nil {
365			var conflict *store.ErrRestoreConflict
366			switch {
367			case errors.Is(err, store.ErrSnapshotNotFound):
368				writeError(w, http.StatusNotFound, "snapshot not found")
369				return
370			case errors.As(err, &conflict):
371				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
372				return
373			default:
374				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
375				return
376			}
377		}
378	
379		writeJSON(w, http.StatusOK, result)
380	}
381	
382	// parseCursorPath reports whether raw is a decimal non-negative integer and
383	// returns its value. Signs, fractions and other adornments are rejected.
384	func parseCursorPath(raw string) (int64, bool) {
385		if raw == "" {
386			return 0, false
387		}
388		for _, c := range raw {
389			if c < '0' || c > '9' {
390				return 0, false
391			}
392		}
393		n, err := strconv.ParseInt(raw, 10, 64)
394		if err != nil {
395			return 0, false
396		}
397		return n, true
398	}
399	
400	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
401	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
402		var n int64
403		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
404			return 0, false
405		}
406		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
407		// require the literal to contain no fraction or exponent.
408		trimmed := strings.TrimSpace(string(raw))
409		if trimmed == "" || trimmed[0] == '-' {
410			return 0, false
411		}
412		for _, c := range trimmed {
413			if c < '0' || c > '9' {
414				return 0, false
415			}
416		}
417		return n, true
418	}
419	
420	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
421	// strings, booleans, null and negative numbers are rejected.
422	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
423		n, ok := parseNonNegativeInt(raw)
424		if !ok || n < 1 {
425			return 0, false
426		}
427		return n, true
428	}
429	
430	// isJSONObject reports whether raw decodes to a JSON object (not null, an
431	// array or a scalar).
432	func isJSONObject(raw json.RawMessage) bool {
433		var m map[string]json.RawMessage
434		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
435			return false
436		}
437		return true
438	}
439	
440	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
441		documentID := r.PathValue("documentID")
442		q := r.URL.Query()
443	
444		after := int64(0)
445		if raw := q.Get("after"); raw != "" {
446			v, err := strconv.ParseInt(raw, 10, 64)
447			if err != nil || v < 0 {
448				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
449				return
450			}
451			after = v
452		}
453	
454		limit := int64(defaultListLimit)
455		if raw := q.Get("limit"); raw != "" {
456			v, err := strconv.ParseInt(raw, 10, 64)
457			if err != nil || v < 1 || v > maxListLimit {
458				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
459				return
460			}
461			limit = v
462		}
463	
464		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
465		if err != nil {
466			writeError(w, http.StatusInternalServerError, "failed to list changes")
467			return
468		}
469	
470		writeJSON(w, http.StatusOK, map[string]any{
471			"changes":    changes,
472			"nextCursor": nextCursor,
473		})
474	}
475	
476	func writeJSON(w http.ResponseWriter, status int, v any) {
477		w.Header().Set("Content-Type", "application/json")
478		w.WriteHeader(status)
479		_ = json.NewEncoder(w).Encode(v)
480	}
481	
482	func writeError(w http.ResponseWriter, status int, message string) {
483		writeJSON(w, status, map[string]string{"error": message})
484	}
