487		// Same id repost -> idempotent with embedded result.
488		w, body = mergeBody(t, h, "doc", map[string]any{
489			"deviceId": "dev", "baseCursor": 1,
490			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 1}},
491		})
492		if w.Code != 200 || body["outcome"] != "idempotent" || body["cursor"].(float64) != 1 {
