497			t.Fatalf("embedded result = %v", res)
498		}
499	
500		// Same id, different payload -> 409.
501		w, _ = mergeBody(t, h, "doc", map[string]any{
502			"deviceId": "dev", "baseCursor": 1,
503			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 2}},
504		})
505		if w.Code != http.StatusConflict {
506			t.Fatalf("conflict = %d body=%s", w.Code, w.Body.String())
507		}
508	
509		// Seed a second object {"b":2} at cursor 2.
510		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
511			"deviceId": "dev",
512			"changes":  []any{map[string]any{"id": "c2", "payload": map[string]any{"b": 2}}},
513		})
514		if w.Code != 200 {
515			t.Fatal(w.Body.String())
516		}
517	
518		// Stale client at baseCursor 1 posts {"c":3}: disjoint from later {"b":2} -> merged cursor 3.
519		w, body = mergeBody(t, h, "doc", map[string]any{
520			"deviceId": "dev", "baseCursor": 1,
521			"change": map[string]any{"id": "c3", "payload": map[string]any{"c": 3}},
522		})
