524			t.Fatalf("merged = %d %v body=%s", w.Code, body, w.Body.String())
525		}
526	
527		// Stale client posts a payload colliding with later key "b" -> 409 zero write.
528		before, _, _ := s.ListChanges("doc", 0, 100)
529		w, _ = mergeBody(t, h, "doc", map[string]any{
530			"deviceId": "dev", "baseCursor": 0,
531			"change": map[string]any{"id": "c4", "payload": map[string]any{"b": 99}},
532		})
