534			t.Fatalf("clash = %d body=%s", w.Code, w.Body.String())
535		}
536		after, _, _ := s.ListChanges("doc", 0, 100)
537		if len(after) != len(before) {
538			t.Fatalf("conflict changed row count: before=%d after=%d", len(before), len(after))
539		}
540	}
