		if w.Code != http.StatusBadRequest {
			t.Fatalf("cursor %q status = %d, want 400", p, w.Code)
		}
		var errBody map[string]string
		if err := json.Unmarshal(w.Body.Bytes(), &errBody); err != nil || errBody["error"] == "" {
