		t.Fatal(err)
	}

	// Concurrent identical puts: exactly one creator, no errors.
	var wg sync.WaitGroup
	var mu sync.Mutex
	creators := 0
	for i := 0; i < 8; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			created, err := s.PutSnapshot("doc", 1, json.RawMessage(`{"v":1}`))
