		t.Fatal(err)
	}

	s2, err := store.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	h2 := NewHandler(s2)

	// Registration and session are still known: retries are idempotent.
	w, body = postJSON(t, h2, "/v1/devices", map[string]any{"deviceId": "dev-1"})
	if w.Code != http.StatusOK || body["created"] != false {
